## Step 1 - the two moving parts

```ts
// 1. save, after signing in
await page.context().storageState({ path: "state.json" });

// 2. load, when the test browser starts
use: { storageState: "state.json" }
```

Where you save decides the shape of the solution:

| Where you save | Runs | Good for |
|---|---|---|
| `globalSetup` | once per whole run | one shared user - today's lesson |
| a setup **project** | once, with tracing and retries | real suites - [day2_3](/learn/w5/d2/p3) |
| `beforeAll` in a file | once per file | one file's special user |

import { REPO_ROOT } from "../_shared/deno-helpers.ts";

// REPO_ROOT, not a bare relative path: the kernel's cwd is this notebook's folder.
const setupSource = await Deno.readTextFile(`${REPO_ROOT}/week5/generated/day2-auth.setup.ts`);
console.log(setupSource);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day2-auth.setup.ts", `// Week 5, Day 2 — log in once, before any test runs.
//
// This is a globalSetup module: Playwright runs it once, before the suite. It gets
// no fixtures (there is no test yet), so it launches its own browser.
//
// Its only job is to sign in and write the resulting session to a file. Every test
// then starts from that file and never logs in.
import { chromium, type FullConfig } from "@playwright/test";
import * as path from "node:path";

export const STATE_FILE = path.join(__dirname, ".auth", "saucedemo.json");

export default async function globalSetup(_config: FullConfig): Promise<void> {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.goto("https://www.saucedemo.com/");
  await page.locator("#user-name").fill("standard_user");
  await page.locator("#password").fill("secret_sauce");
  await page.locator("#login-button").click();
  await page.waitForURL(/inventory/);

  // storageState() returns cookies + localStorage. Writing it to \`path\` saves it.
  await page.context().storageState({ path: STATE_FILE });

  await browser.close();
  console.log(\`globalSetup: signed in once, session saved to \${path.basename(STATE_FILE)}\`);
}
`);

await writeProjectFile("week5/generated/day2-storage-state.config.ts", `// Week 5, Day 2 — the config that ties globalSetup to storageState.
//
// Three lines do the whole job:
//   globalSetup          -> run the login module once, first
//   use.storageState     -> start every test from the file it wrote
//   testMatch            -> only this day's spec
//
// This needs its own config because the spec depends on the setup having run. A
// default-suite run on a clean checkout must not assume that.
//
//   npx playwright test -c week5/generated/day2-storage-state.config.ts
import { defineConfig, devices } from "@playwright/test";
import * as path from "node:path";

export default defineConfig({
  testDir: ".",
  testMatch: ["day2-storage-state.authdemo.ts"],
  globalSetup: "./day2-auth.setup.ts",
  reporter: [["list"]],
  use: {
    ...devices["Desktop Chrome"],
    baseURL: "https://www.saucedemo.com",
    // Every test in this project starts already signed in.
    storageState: path.join(__dirname, ".auth", "saucedemo.json"),
  },
});
`);

await writeProjectFile("week5/generated/day2-storage-state.authdemo.ts", `// Week 5, Day 2 — tests that never log in.
//
// Filename note: .authdemo.ts, not .spec.ts. The root config collects every
// week*/**/*.spec.ts and has no globalSetup, so these tests would run anonymously
// there and fail. Its own config picks them up instead.
//
// Look for a login step below. There isn't one. The session came from the file
// globalSetup wrote, so each test opens straight into the signed-in app.
//
// Uses saucedemo, not the course banking app: that app keeps NO cookies and NO
// localStorage (measured — its login is in-memory only), so a saved state file
// would be empty and change nothing. storageState only helps where a real session
// is persisted.
//
//   npx playwright test -c week5/generated/day2-storage-state.config.ts
import { test, expect } from "@playwright/test";

test.describe("Signed in, with no login step anywhere", () => {
  test("Step 1 — the inventory page is reachable directly", async ({ page }) => {
    await page.goto("/inventory.html");

    // 6 products, verified. Without the session this page renders empty.
    await expect(page.locator(".inventory_item")).toHaveCount(6);
  });

  test("Step 2 — a second test is also already signed in", async ({ page }) => {
    await page.goto("/inventory.html");
    await expect(page.locator(".inventory_item").first()).toBeVisible();
    // The burger menu only exists for a signed-in user.
    await expect(page.locator("#react-burger-menu-btn")).toBeVisible();
  });

  test("Step 3 — the session survives navigation", async ({ page }) => {
    await page.goto("/inventory.html");
    await page.locator(".inventory_item").first().locator("button").click();
    await page.locator(".shopping_cart_link").click();
    await expect(page).toHaveURL(/cart/);
    await expect(page.locator(".cart_item")).toHaveCount(1);
  });

  test("Step 4 — an explicitly anonymous test proves the state is doing the work", async ({ browser }) => {
    // storageState is a \`use\` option, so it can be turned OFF for one test by
    // building a context without it. Same app, no session.
    const anonymous = await browser.newContext({ storageState: undefined });
    const page = await anonymous.newPage();

    await page.goto("https://www.saucedemo.com/inventory.html");
    await expect(page.locator(".inventory_item")).toHaveCount(0);

    await anonymous.close();
  });
});
`);

// Expected: 4 passed. Watch for the globalSetup line printed before the tests.
await runSpec("week5/generated/day2-storage-state.authdemo.ts", { extraArgs: ["-c", "week5/generated/day2-storage-state.config.ts"] });

## A setup project

```ts
// playwright.config.ts
projects: [
  { name: "setup", testMatch: /.*\.setup\.ts/ },
  {
    name: "chromium",
    use: { ...devices["Desktop Chrome"], storageState: ".auth/user.json" },
    dependencies: ["setup"],        // <- run "setup" first, every time
  },
],
```

`dependencies` is the whole trick: `chromium` will not start until `setup` has passed.

| | `globalSetup` | setup project |
|---|---|---|
| Appears in the report | no | **yes** |
| Traces / screenshots on failure | no | **yes** |
| Can retry | no | **yes** |
| Blocks the suite when it fails | yes, confusingly | yes, with a named failing test |

And the setup file becomes a test:

```ts
// auth.setup.ts
import { test as setup, expect } from "@playwright/test";

setup("authenticate", async ({ page }) => {
  await page.goto("/");
  await page.locator("#user-name").fill("standard_user");
  await page.locator("#password").fill("secret_sauce");
  await page.locator("#login-button").click();
  await expect(page.locator(".inventory_list")).toBeVisible();  // assert, don't just wait
  await page.context().storageState({ path: ".auth/user.json" });
});
```

Note `expect` rather than `waitForURL`: as a test it is allowed to assert, and a failed assertion
here names the problem exactly.

// Which project claims which spec? testMatch is just a pattern test - run it here.
const roleProjects = [
  { name: "admin",    testMatch: /.*\.admin\.spec\.ts/,    state: ".auth/admin.json" },
  { name: "customer", testMatch: /.*\.customer\.spec\.ts/, state: ".auth/customer.json" },
];

for (const file of ["payees.admin.spec.ts", "cart.customer.spec.ts", "login.spec.ts"]) {
  const owner = roleProjects.find((p) => p.testMatch.test(file));
  console.log(file.padEnd(26), "->", owner ? `${owner.name}  (${owner.state})` : "no project: NEVER RUNS");
}
